import { ProfilePatch } from './types';

const invalid = () => new Error('invalid profile');

export function parseProfile(input: unknown): ProfilePatch {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) throw invalid();
  const proto = Object.getPrototypeOf(input);
  if (proto !== Object.prototype && proto !== null) throw invalid();
  const keys = Reflect.ownKeys(input);
  for (const key of keys) if (key !== 'displayName' && key !== 'tags') throw invalid();
  const has = (k: string) => keys.includes(k);
  const record = input as Record<string, unknown>;

  let displayName: ProfilePatch['displayName'] = { kind: 'keep' };
  let tags: ProfilePatch['tags'] = { kind: 'keep' };

  if (has('displayName')) {
    const raw = record.displayName;
    if (raw === null) displayName = { kind: 'set', value: null };
    else if (typeof raw === 'string') {
      const value = raw.trim();
      if (value.length < 1 || value.length > 40) throw invalid();
      displayName = { kind: 'set', value };
    } else throw invalid();
  }

  if (has('tags')) {
    const raw = record.tags;
    if (raw === null) tags = { kind: 'set', value: [] };
    else if (Array.isArray(raw)) {
      if (raw.length > 5) throw invalid();
      const seen = new Set<string>();
      const out: string[] = [];
      for (let i = 0; i < raw.length; i++) {
        if (!(i in raw)) throw invalid();
        const item: unknown = raw[i];
        if (typeof item !== 'string') throw invalid();
        const t = item.trim();
        if (t.length < 1 || t.length > 12 || seen.has(t)) throw invalid();
        seen.add(t);
        out.push(t);
      }
      tags = { kind: 'set', value: out };
    } else throw invalid();
  }
  return { displayName, tags };
}

